# Initially generated by GitHub Copilot.
"""Load and validate vendoring repo policy."""

from __future__ import annotations

import json
from dataclasses import dataclass
from functools import lru_cache

from mb_cmn import paths

# The category column answers "is this copy being kept up?", and mechanism answers "by
# what?" (``5fc4a77``).  A closed set, checked here, because the two halves of the
# vocabulary drifted apart in both directions before #60: ``deferred`` went on being read
# by ``discover._compare_hint_from_inventory_row`` for over three months after ``16eaa69``
# and ``7434016`` retired the last repo that declared it, and nothing would have caught a
# repo declaring a word no reader knew.  Checking membership here shuts the second door
# and makes the first visible, since a word dropped from this set is a word every
# declaration of which the loader then rejects by name.
#
# * ``active``     -- kept up, and known to be up to date.
# * ``generated``  -- written by a generator here, not maintained in the destination.
# * ``stale``      -- measured, and behind.
# * ``unmeasured`` -- nobody has looked at how far it has drifted.  Named for what is
#   missing rather than for why, so it says nothing that can go out of date, and it has
#   one exit: measure it.  ``doc/PLAN-evacuate-public-repos-programme.md``'s Appendix B is the
#   statement of the one repo in it, diffable-pointed-hebrew.
CATEGORY_VALUES = frozenset({"active", "generated", "stale", "unmeasured"})


@dataclass(frozen=True)
class RepoPolicy:
    name: str
    ignore: bool
    scan_provenance: bool
    default_category: str | None
    default_mechanism: str | None
    default_provenance_doc: str | None
    pkg_scan_roots: dict[str, tuple[str, ...]]
    comment: str | None


@dataclass(frozen=True)
class OverridePolicy:
    dest_repo: str
    dest_path: str
    src_pkg: str
    category: str | None
    mechanism: str | None
    provenance_doc: str | None
    notes: str | None
    comment: str | None


@dataclass(frozen=True)
class ForeignVendoredPolicy:
    """Files vendored into a workspace repo from a source repo other than MAM-basics.

    The audit never measures these -- category and mechanism are the source repo's
    business -- so an entry names only the destination, the source repo, and the copied
    files. Their one consumer is repo_util/maintenance_policy.py's vendored_overrides,
    which keeps the black sweep off them; dest_repo is deliberately not required to be
    in the repos object, so nothing obliges the audit or the suite to resolve the
    destination repo on disk.
    """

    dest_repo: str
    src_repo: str
    dest_paths: tuple[str, ...]
    comment: str | None


@dataclass(frozen=True)
class VendoringPolicy:
    comment: str | None
    source_pkg_dirs: dict[str, str]
    repos: dict[str, RepoPolicy]
    overrides: tuple[OverridePolicy, ...]
    foreign_vendored: tuple[ForeignVendoredPolicy, ...]


_POLICY_PATH = paths.repo_root() / "in" / "vendoring_policy.json"


def _expect_dict(value: object, label: str) -> dict[object, object]:
    if not isinstance(value, dict):
        raise ValueError(f"{label} must be an object")
    return value


def _expect_bool(value: object, label: str) -> bool:
    if not isinstance(value, bool):
        raise ValueError(f"{label} must be a boolean")
    return value


def _expect_str_or_none(value: object, label: str) -> str | None:
    if value is None or isinstance(value, str):
        return value
    raise ValueError(f"{label} must be a string or null")


def _expect_category_or_none(value: object, label: str) -> str | None:
    category = _expect_str_or_none(value, label)
    if category is not None and category not in CATEGORY_VALUES:
        raise ValueError(
            f"{label} must be one of {sorted(CATEGORY_VALUES)}, not {category!r}"
        )
    return category


def _expect_rel_path(value: object, label: str) -> str:
    if not isinstance(value, str) or not value:
        raise ValueError(f"{label} must be a non-empty string")
    if "\\" in value:
        raise ValueError(f"{label} must use forward slashes: {value!r}")
    if value.startswith("/") or value.endswith("/"):
        raise ValueError(f"{label} must be a clean relative path: {value!r}")
    return value


def _unexpected_keys(data: dict[object, object], allowed: set[str], label: str) -> None:
    unexpected = sorted(str(key) for key in data.keys() if key not in allowed)
    if unexpected:
        raise ValueError(f"Unexpected keys in {label}: {unexpected}")


def _load_repo(
    repo_name: str,
    raw_repo: dict[object, object],
    source_pkg_dirs: dict[str, str],
) -> RepoPolicy:
    _unexpected_keys(
        raw_repo,
        {
            "comment",
            "ignore",
            "scan_provenance",
            "default_category",
            "default_mechanism",
            "default_provenance_doc",
            "pkg_scan_roots",
        },
        f"repos.{repo_name}",
    )
    pkg_scan_roots_raw = _expect_dict(
        raw_repo.get("pkg_scan_roots"), f"repos.{repo_name}.pkg_scan_roots"
    )
    pkg_scan_roots: dict[str, tuple[str, ...]] = {}
    for src_pkg, raw_roots in pkg_scan_roots_raw.items():
        if src_pkg not in source_pkg_dirs:
            raise ValueError(
                f"repos.{repo_name}.pkg_scan_roots has unknown source pkg {src_pkg!r}"
            )
        if not isinstance(raw_roots, list) or not raw_roots:
            raise ValueError(
                f"repos.{repo_name}.pkg_scan_roots.{src_pkg} must be a non-empty list"
            )
        pkg_scan_roots[str(src_pkg)] = tuple(
            _expect_rel_path(raw_root, f"repos.{repo_name}.pkg_scan_roots.{src_pkg}[]")
            for raw_root in raw_roots
        )

    ignore = _expect_bool(raw_repo.get("ignore"), f"repos.{repo_name}.ignore")
    if ignore and pkg_scan_roots:
        raise ValueError(f"Ignored repo {repo_name} must not define pkg_scan_roots")

    scan_provenance = _expect_bool(
        raw_repo.get("scan_provenance"), f"repos.{repo_name}.scan_provenance"
    )
    default_category = _expect_category_or_none(
        raw_repo.get("default_category"), f"repos.{repo_name}.default_category"
    )
    default_mechanism = _expect_str_or_none(
        raw_repo.get("default_mechanism"), f"repos.{repo_name}.default_mechanism"
    )
    default_provenance_doc = _expect_str_or_none(
        raw_repo.get("default_provenance_doc"),
        f"repos.{repo_name}.default_provenance_doc",
    )
    if ignore:
        if any(
            value is not None
            for value in (default_category, default_mechanism, default_provenance_doc)
        ):
            raise ValueError(f"Ignored repo {repo_name} must not define defaults")
    else:
        if None in (default_category, default_mechanism, default_provenance_doc):
            raise ValueError(f"Non-ignored repo {repo_name} must define all defaults")

    return RepoPolicy(
        name=repo_name,
        ignore=ignore,
        scan_provenance=scan_provenance,
        default_category=default_category,
        default_mechanism=default_mechanism,
        default_provenance_doc=default_provenance_doc,
        pkg_scan_roots=pkg_scan_roots,
        comment=_expect_str_or_none(
            raw_repo.get("comment"), f"repos.{repo_name}.comment"
        ),
    )


def _load_override(
    index: int,
    raw_override: dict[object, object],
    repos: dict[str, RepoPolicy],
    source_pkg_dirs: dict[str, str],
) -> OverridePolicy:
    label = f"overrides[{index}]"
    _unexpected_keys(
        raw_override,
        {
            "comment",
            "dest_repo",
            "dest_path",
            "src_pkg",
            "category",
            "mechanism",
            "provenance_doc",
            "notes",
        },
        label,
    )
    dest_repo = raw_override.get("dest_repo")
    if not isinstance(dest_repo, str) or dest_repo not in repos:
        raise ValueError(f"{label}.dest_repo must name a known repo")
    if repos[dest_repo].ignore:
        raise ValueError(f"{label}.dest_repo targets ignored repo {dest_repo}")
    src_pkg = raw_override.get("src_pkg")
    if not isinstance(src_pkg, str) or src_pkg not in source_pkg_dirs:
        raise ValueError(f"{label}.src_pkg must name a known source package")
    return OverridePolicy(
        dest_repo=dest_repo,
        dest_path=_expect_rel_path(raw_override.get("dest_path"), f"{label}.dest_path"),
        src_pkg=src_pkg,
        category=_expect_category_or_none(
            raw_override.get("category"), f"{label}.category"
        ),
        mechanism=_expect_str_or_none(
            raw_override.get("mechanism"), f"{label}.mechanism"
        ),
        provenance_doc=_expect_str_or_none(
            raw_override.get("provenance_doc"), f"{label}.provenance_doc"
        ),
        notes=_expect_str_or_none(raw_override.get("notes"), f"{label}.notes"),
        comment=_expect_str_or_none(raw_override.get("comment"), f"{label}.comment"),
    )


def _load_foreign_vendored(
    index: int, raw_entry: dict[object, object]
) -> ForeignVendoredPolicy:
    label = f"foreign_vendored[{index}]"
    _unexpected_keys(
        raw_entry, {"comment", "dest_repo", "src_repo", "dest_paths"}, label
    )
    dest_repo = raw_entry.get("dest_repo")
    if not isinstance(dest_repo, str) or not dest_repo:
        raise ValueError(f"{label}.dest_repo must be a non-empty string")
    src_repo = raw_entry.get("src_repo")
    if not isinstance(src_repo, str) or not src_repo:
        raise ValueError(f"{label}.src_repo must be a non-empty string")
    if src_repo == "MAM-basics":
        raise ValueError(
            f"{label}.src_repo is MAM-basics; a copy sourced here belongs in"
            " overrides or in a repos entry, where the audit measures it"
        )
    raw_paths = raw_entry.get("dest_paths")
    if not isinstance(raw_paths, list) or not raw_paths:
        raise ValueError(f"{label}.dest_paths must be a non-empty list")
    dest_paths = tuple(
        _expect_rel_path(raw_path, f"{label}.dest_paths[]") for raw_path in raw_paths
    )
    return ForeignVendoredPolicy(
        dest_repo=dest_repo,
        src_repo=src_repo,
        dest_paths=dest_paths,
        comment=_expect_str_or_none(raw_entry.get("comment"), f"{label}.comment"),
    )


@lru_cache(maxsize=1)
def load_policy() -> VendoringPolicy:
    raw_top = _expect_dict(
        json.loads(_POLICY_PATH.read_text(encoding="utf-8")), "vendoring policy"
    )
    _unexpected_keys(
        raw_top,
        {"comment", "global", "repos", "overrides", "foreign_vendored"},
        "policy",
    )

    raw_global = _expect_dict(raw_top.get("global"), "policy.global")
    _unexpected_keys(raw_global, {"comment", "source_pkg_dirs"}, "policy.global")
    raw_source_pkg_dirs = _expect_dict(
        raw_global.get("source_pkg_dirs"), "policy.global.source_pkg_dirs"
    )
    source_pkg_dirs = {
        str(src_pkg): _expect_rel_path(
            rel_path, f"policy.global.source_pkg_dirs.{src_pkg}"
        )
        for src_pkg, rel_path in raw_source_pkg_dirs.items()
    }

    raw_repos = _expect_dict(raw_top.get("repos"), "policy.repos")
    repos = {
        str(repo_name): _load_repo(
            str(repo_name), _expect_dict(raw_repo, str(repo_name)), source_pkg_dirs
        )
        for repo_name, raw_repo in raw_repos.items()
    }

    raw_overrides = raw_top.get("overrides")
    if not isinstance(raw_overrides, list):
        raise ValueError("policy.overrides must be a list")
    overrides = tuple(
        _load_override(
            index,
            _expect_dict(raw_override, f"overrides[{index}]"),
            repos,
            source_pkg_dirs,
        )
        for index, raw_override in enumerate(raw_overrides)
    )
    raw_foreign = raw_top.get("foreign_vendored")
    if not isinstance(raw_foreign, list):
        raise ValueError("policy.foreign_vendored must be a list")
    foreign_vendored = tuple(
        _load_foreign_vendored(
            index, _expect_dict(raw_entry, f"foreign_vendored[{index}]")
        )
        for index, raw_entry in enumerate(raw_foreign)
    )

    seen_override_targets: set[tuple[str, str]] = set()
    for override in overrides:
        key = (override.dest_repo, override.dest_path)
        if key in seen_override_targets:
            raise ValueError(f"Duplicate override target: {key}")
        seen_override_targets.add(key)
    for entry in foreign_vendored:
        for dest_path in entry.dest_paths:
            key = (entry.dest_repo, dest_path)
            if key in seen_override_targets:
                raise ValueError(f"Duplicate vendored target: {key}")
            seen_override_targets.add(key)

    return VendoringPolicy(
        comment=_expect_str_or_none(raw_top.get("comment"), "policy.comment"),
        source_pkg_dirs=source_pkg_dirs,
        repos=repos,
        overrides=overrides,
        foreign_vendored=foreign_vendored,
    )
